        load = 1;
        ena = 1;
        data = 4'b1110;
        expected_q = 4'b1110;
        check_q(expected_q);

        // Test 7: Disable load, continue shift
        load = 0;
        ena = 1;
        // q was 4'b1110 -> shift right -> 4'b0111
        expected_q = 4'b0111;
        check_q(expected_q);

        // Test 8: Asynchronous reset during operation
        areset = 1;
        #3;
        if (q !== 4'b0000) begin
            $display("ERROR: Asynchronous reset during operation failed. Got q=%h", q);
